import { ensureLanguages, parseCodeSync, commentNodes } from "@govlab/code-parse";

await ensureLanguages(["go", "typescript", "javascript"]);
function strip(source, lang) {
    const root = parseCodeSync(source, lang);
    return root ? commentNodes(root) : [];
}
